 if(a!=b||p.AirCycleStage!=q.Stage||p.AirCycleAction!=q.Action||p.AirCycleCount!=q.Count||p.AssaultIssued!=q.AssaultIssued||p.PagesOrdered!=q.PagesOrdered||p.StructureOrdered!=q.StructureOrdered||p.AirSortieObservedAt!=q.SortieObservedAt||p.AirCycleDeadline!=q.Deadline||p.AirServiceReadyAt!=q.ServiceReadyAt||p.ObserveUntil!=q.ObserveUntil||p.Intent!=intent||o.Kind!=mapped.Kind||o.Id!=mapped.Id)throw new Exception("Differential mismatch case "+k);count++;
